package com.example.veilark.profile

import org.json.JSONArray
import org.json.JSONObject

/** Declared native capabilities, not evidence that a real flow adapter is ready. */
data class CoreFlowCapabilities(
  val apiVersion: Int,
  val ipv4Tcp: Boolean,
  val ipv4UdpAssociate: Boolean,
  val sessionAuthentication: Boolean,
  val maximumFlows: Int,
  val maximumUdpPayload: Int,
)

/** Independent session credentials generated by the owner, never enrollment material. */
class CoreLoopbackSession(
  val host: String,
  val port: Int,
  internal val username: String,
  internal val password: String,
) {
  init {
    require(host == "127.0.0.1" && port in 1..65535) { "Core requires an IPv4 loopback listener" }
    require(listOf(username, password).all { value ->
      value.length in 1..255 && value.all { it.code in 0x21..0x7e }
    }) { "Core requires bounded ASCII session authentication" }
  }
  override fun toString() = "CoreLoopbackSession(authentication=redacted)"
}

/** JSON intentionally stays out of data-class toString, profiles and diagnostic logs. */
class CoreEphemeralRoutingConfig internal constructor(private val value: String) {
  fun <T> useJson(action: (String) -> T): T = action(value)
  override fun toString() = "CoreEphemeralRoutingConfig(redacted)"
}

/** Preparation only. No service/JNI activation or persistent profile mutation. */
object CoreFlowRoutingConfig {
  fun build(
    session: CoreLoopbackSession,
    capabilities: CoreFlowCapabilities,
    routingMode: String,
    directEntries: String = "",
    vpnEntries: String = "",
    geoRuleSets: ProfileSelection.GeoRuleSets? = null,
    categoryRuleSets: Map<String, String> = emptyMap(),
    applicationMode: String = ProfileSelection.APPS_ALL,
    dpiMode: String = ProfileSelection.DPI_OFF,
    applications: Set<String> = emptySet(),
    vpnPackage: String? = null,
    validateConfig: (String) -> Unit,
  ): CoreEphemeralRoutingConfig {
    require(capabilities.apiVersion == 1 && capabilities.ipv4Tcp &&
      capabilities.ipv4UdpAssociate && capabilities.sessionAuthentication &&
      capabilities.maximumFlows in 1..64 && capabilities.maximumUdpPayload in 1..1252) {
      "Core shared routing capabilities are unavailable"
    }
    require(dpiMode == ProfileSelection.DPI_OFF) { "Core shared routing does not support TLS fragmentation" }
    val socks = JSONObject()
      .put("type", "socks").put("tag", ProfileSelection.AUTOMATIC_TAG)
      .put("server", session.host).put("server_port", session.port).put("version", "5")
      .put("username", session.username).put("password", session.password)
      // Both TCP and standard UDP ASSOCIATE; no UoT or OS domain resolver.
      .put("domain_resolver", JSONObject().put("server", "secure-dns").put("strategy", "ipv4_only"))
    val template = SubscriptionParser().createRoutingTemplate(JSONArray()
      .put(socks).put(JSONObject().put("type", "direct").put("tag", "direct")))
    template.getJSONObject("route").put("default_domain_resolver", "secure-dns")
    val routed = ProfileSelection.applyRouting(template.toString(), routingMode,
      directEntries, vpnEntries, geoRuleSets, categoryRuleSets)
    val root = JSONObject(ProfileSelection.applyApplications(routed, applicationMode, applications, vpnPackage))
    val route = root.getJSONObject("route")
    val policy = route.optJSONArray("rules") ?: JSONArray()
    val rules = JSONArray()
      // Keep the existing dual-family TUN custody, then reject IPv6 before Direct too.
      .put(JSONObject().put("ip_version", 6).put("action", "reject"))
      .put(JSONObject().put("action", "sniff"))
      .put(JSONObject().put("port", 53).put("action", "hijack-dns"))
      // Resolve destinations, not merely the proxy's literal loopback address.
      // Omitting server retains existing Direct/RU DNS selection; final DNS uses Core DoH.
      .put(JSONObject().put("action", "resolve").put("strategy", "ipv4_only"))
    repeat(policy.length()) { index ->
      val rule = policy.getJSONObject(index)
      if (rule.optString("action") != "sniff") {
        if (rule.optString("outbound") == ProfileSelection.AUTOMATIC_TAG) {
          rule.put("udp_disable_domain_unmapping", true)
        }
        rules.put(rule)
      }
    }
    rules.put(JSONObject().put("outbound", ProfileSelection.AUTOMATIC_TAG)
      .put("udp_disable_domain_unmapping", true))
    route.put("rules", rules)
    val value = root.toString(2)
    // Production caller must pass actual current Libbox.checkConfig; never log the JSON.
    validateConfig(value)
    return CoreEphemeralRoutingConfig(value)
  }
}
